import React, { useState, useCallback } from 'react';
import './App.css';

function App() {
  const [selectedElement, setSelectedElement] = useState(null);
  const [canvasElements, setCanvasElements] = useState([
    // Демо wireframe элементы как на скриншоте
    { id: 'header', type: 'header', x: 100, y: 50, width: 600, height: 80, name: 'Шапка' },
    { id: 'nav1', type: 'nav', x: 120, y: 100, width: 120, height: 40, name: 'Навигация 1' },
    { id: 'nav2', type: 'nav', x: 260, y: 100, width: 120, height: 40, name: 'Навигация 2' },
    { id: 'nav3', type: 'nav', x: 400, y: 100, width: 120, height: 40, name: 'Навигация 3' },
    { id: 'nav4', type: 'nav', x: 540, y: 100, width: 120, height: 40, name: 'Навигация 4' },
    { id: 'hero', type: 'hero', x: 120, y: 160, width: 580, height: 60, name: 'Герой секция' },
    { id: 'content1', type: 'content', x: 120, y: 240, width: 180, height: 120, name: 'Контент 1' },
    { id: 'content2', type: 'content', x: 320, y: 240, width: 180, height: 120, name: 'Контент 2' },
    { id: 'content3', type: 'content', x: 520, y: 240, width: 180, height: 120, name: 'Контент 3' },
    { id: 'sidebar', type: 'sidebar', x: 120, y: 380, width: 120, height: 100, name: 'Сайдбар' },
    { id: 'footer', type: 'footer', x: 120, y: 500, width: 580, height: 60, name: 'Подвал' }
  ]);

  const [chatMessages, setChatMessages] = useState([
    {
      id: '1',
      type: 'ai',
      content: '**План создания дизайна:**\n\n1. **Анализ требований**\n2. **Структура сайта** - создание wireframe\n3. **Дизайн компонентов**\n4. **Финальная компоновка**\n\nПодтверждаете план? Если да, начну с wireframe.',
      timestamp: new Date()
    }
  ]);

  const [zoom, setZoom] = useState(100);
  const [inputValue, setInputValue] = useState('');
  const [currentPrompt, setCurrentPrompt] = useState('Создать wireframe для современного веб-сайта с шапкой, hero-секцией, блоком контента с карточками и подвалом');
  const [canvasOffset, setCanvasOffset] = useState({ x: 0, y: 0 });
  const [isDragging, setIsDragging] = useState(false);
  const [dragStart, setDragStart] = useState({ x: 0, y: 0 });

  const handleElementSelect = useCallback((elementId) => {
    const element = canvasElements.find(el => el.id === elementId);
    setSelectedElement(element);
  }, [canvasElements]);

  const handleCanvasClick = useCallback(() => {
    setSelectedElement(null);
  }, []);

  const handleSendMessage = useCallback(async (message) => {
    if (!message.trim()) return;

    setChatMessages(prev => [
      ...prev,
      { id: Date.now() + '-user', type: 'user', content: message, timestamp: new Date() }
    ]);

    setTimeout(() => {
      setChatMessages(prev => [
        ...prev,
        { 
          id: Date.now() + '-ai', 
          type: 'ai', 
          content: 'Превосходно! Это wireframe базовой структуры.\n\n**Управление:**\n• Клик на элемент - выделение\n• Колесо мыши - зум\n• Перетаскивание - панорамирование', 
          timestamp: new Date() 
        }
      ]);
    }, 1000);
  }, []);

  // Управление зумом
  const handleZoomIn = () => setZoom(prev => Math.min(prev + 10, 200));
  const handleZoomOut = () => setZoom(prev => Math.max(prev - 10, 50));
  const handleResetZoom = () => setZoom(100);

  // Обработка перетаскивания канваса
  const handleMouseDown = (e) => {
    if (e.target.classList.contains('canvas-area')) {
      setIsDragging(true);
      setDragStart({ x: e.clientX - canvasOffset.x, y: e.clientY - canvasOffset.y });
    }
  };

  const handleMouseMove = (e) => {
    if (isDragging) {
      setCanvasOffset({
        x: e.clientX - dragStart.x,
        y: e.clientY - dragStart.y
      });
    }
  };

  const handleMouseUp = () => {
    setIsDragging(false);
  };

  return (
    <div className="app">
      {/* Левая панель - Чат */}
      <div className="chat-panel">
        <div className="panel-header">
          <span>💬</span> UI Design Assistant
        </div>

        <div className="chat-messages">
          {chatMessages.map((message) => (
            <div key={message.id} className={`chat-message ${message.type}`}>
              <div className="message-content">
                {message.content.split('\n').map((line, i) => (
                  <div key={i}>{line}</div>
                ))}
              </div>
            </div>
          ))}
        </div>

        <div className="chat-input">
          <textarea
            value={inputValue}
            onChange={(e) => setInputValue(e.target.value)}
            placeholder="Опишите что хотите создать"
            rows={2}
          />
          <button 
            onClick={() => {
              handleSendMessage(inputValue);
              setInputValue('');
            }}
            disabled={!inputValue.trim()}
          >
            Отправить
          </button>
        </div>
      </div>

      {/* Центральная область - Канвас */}
      <div className="design-canvas">
        <div className="canvas-toolbar">
          <button onClick={handleZoomOut}>🔍</button>
          <button onClick={handleResetZoom}>🔍</button>
          <button onClick={handleZoomIn}>🔍</button>
          <button>⚙️</button>
          <span className="zoom-level">{zoom}%</span>
        </div>

        <div 
          className="canvas-area"
          onMouseDown={handleMouseDown}
          onMouseMove={handleMouseMove}
          onMouseUp={handleMouseUp}
          style={{ 
            transform: `scale(${zoom / 100}) translate(${canvasOffset.x}px, ${canvasOffset.y}px)`,
            cursor: isDragging ? 'grabbing' : 'grab'
          }}
        >
          <div className="wireframe-title">Основной wireframe</div>

          {canvasElements.map((element) => (
            <div
              key={element.id}
              className={`canvas-element ${element.type} ${selectedElement?.id === element.id ? 'selected' : ''}`}
              style={{
                left: element.x,
                top: element.y,
                width: element.width,
                height: element.height,
              }}
              onClick={(e) => {
                e.stopPropagation();
                handleElementSelect(element.id);
              }}
            >
              <div className="element-label">{element.name}</div>
            </div>
          ))}
        </div>

        <div className="canvas-help">
          <div>✋ Средняя кнопка: панорамирование</div>
          <div>🖱️ Колесо: масштаб • Escape: снять выделение</div>
        </div>
      </div>

      {/* Правая панель */}
      {selectedElement && (
        <div className="properties-panel">
          <div className="panel-header">
            <span>{selectedElement.name}</span>
            <button onClick={() => setSelectedElement(null)}>✕</button>
          </div>

          <div className="properties-tabs">
            <div className="tab active">✏️ Промпт</div>
            <div className="tab">📝 Код</div>
          </div>

          <div className="properties-content">
            <div className="prompt-section">
              <label>Промпт для генерации</label>
              <textarea
                value={currentPrompt}
                onChange={(e) => setCurrentPrompt(e.target.value)}
                rows={4}
              />
              <button className="generate-btn">Сгенерировать заново</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

export default App;
